async function events(){const d=await api('/api/events');$('events').innerHTML='<div class="mb-5"><p class="text-xs uppercase tracking-wider text-blue-600 font-bold">Department activities</p><h2 class="text-3xl font-extrabold">Events & opportunities</h2></div><div class="grid md:grid-cols-3 gap-4">'+(d.map(x=>'<article class="card bg-white dark:bg-slate-900 rounded-2xl p-5"><b class="text-emerald-600">EVENT</b><h3 class="font-bold text-lg mt-2">'+E(x.title)+'</h3><p class="text-sm text-slate-500 mt-2">'+E(x.description||'')+'</p><p class="text-sm font-semibold mt-4">'+new Date(x.event_date).toLocaleString()+'</p><p class="text-xs text-slate-500">'+E(x.location||'Department campus')+'</p>'+(x.registration_url?'<a class="text-blue-600 text-sm font-semibold inline-block mt-3" href="'+E(x.registration_url)+'" target="_blank" rel="noopener">Register ↗</a>':'')+'</article>').join('')||'<p class="text-slate-500">No events.</p>')+'</div>'}
