      $('genericAdminV6').onsubmit=async e=>{e.preventDefault();try{const b={};if(section==='events')Object.assign(b,{title:$('gvTitle').value,event_date:new Date($('gvDate').value).toISOString(),location:$('gvLocation').value,description:$('gvDesc').value});else if(section==='exams')Object.assign(b,{subject:$('gvTitle').value,exam_type:$('gvSubject').value||'Internal',class_code:$('gvClass').value,exam_date:new Date($('gvDate').value).toISOString(),room:$('gvLocation').value});else if(section==='assignments')Object.assign(b,{title:$('gvTitle').value,subject:$('gvSubject').value,class_code:$('gvClass').value,due_at:new Date($('gvDate').value).toISOString(),description:$('gvDesc').value});else Object.assign(b,{title:$('gvTitle').value,subject:$('gvSubject').value,class_code:$('gvClass').value,description:$('gvDesc').value});await api(cfg.post,{method:'POST',body:JSON.stringify(b)});msg(cfg.label.slice(0,-1)+' created');adminLoad(section)}catch(err){msg(err.message)}};p.querySelectorAll('[data-cdelete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this record?'))return;try{await api('/api/'+section+'/'+b.dataset.id,{method:'DELETE'});msg('Record deleted');adminLoad(section)}catch(e){msg(e.message)}});p.querySelectorAll('[data-cedit]').forEach(b=>b.onclick=()=>adminEditContent(section,b.dataset.id));return;
