async function contentManager(){
  if(!me||me.role!=='ADMIN')return;
  let m=$('contentManager');
  if(!m){
    m=document.createElement('div');
    m.id='contentManager';
    m.className='fixed inset-0 z-[95] bg-slate-950/80 p-3 sm:p-6 overflow-auto';
    document.body.append(m);
  }
  m.innerHTML='<div class="max-w-6xl mx-auto bg-white rounded-2xl p-5 sm:p-7"><div class="flex justify-between items-start gap-3"><div><p class="text-xs uppercase tracking-widest text-blue-600 font-bold">Administrator</p><h2 class="text-2xl font-extrabold">Content manager</h2><p class="text-sm text-slate-500 mt-1">Edit or remove academic records without leaving the portal.</p></div><button id="closeContentManager" class="text-slate-400 text-xl">✕</button></div><div id="contentManagerBody" class="mt-6 grid lg:grid-cols-2 gap-4"></div></div>';
  m.classList.remove('hidden');
  $('closeContentManager').onclick=()=>m.remove();

  const [eventsData,assignmentsData,materialsData,examsData]=await Promise.all([
    api('/api/events'),
    api('/api/assignments?class_code='),
    api('/api/materials?class_code='),
    api('/api/exams?class_code=')
  ]);

  const renderSection=(items,type,label)=>{
    const rows=items.slice(0,30).map(x=>{
      const title=E(x.title||x.subject);
      const meta=E(x.subject||x.event_type||x.exam_type||'')+(x.class_code?' • '+E(x.class_code):'');
      return '<div class="border rounded-xl p-3 flex justify-between gap-3"><div class="min-w-0"><b class="text-sm">'+title+'</b><div class="text-xs text-slate-500 mt-1">'+meta+'</div></div><div class="flex gap-2 shrink-0"><button class="text-xs text-blue-600" data-content-edit="'+type+'" data-id="'+E(x.id)+'">Edit</button><button class="text-xs text-red-600" data-content-delete="'+type+'" data-id="'+E(x.id)+'">Delete</button></div></div>';
    }).join('');
    return '<section class="border rounded-2xl p-4"><div class="flex justify-between items-center mb-3"><b>'+label+'</b><span class="text-xs text-slate-400">'+items.length+' records</span></div><div class="space-y-2">'+(rows||'<p class="text-xs text-slate-500">No records.</p>')+'</div></section>';
  };

  $('contentManagerBody').innerHTML=
    renderSection(eventsData,'event','Events')+
    renderSection(assignmentsData,'assignment','Assignments')+
    renderSection(materialsData,'material','Materials')+
    renderSection(examsData,'exam','Exams');

  m.querySelectorAll('[data-content-delete]').forEach(button=>{
    button.onclick=async()=>{
      if(!confirm('Delete this record?'))return;
      const base={event:'/api/events/',assignment:'/api/assignments/',material:'/api/materials/',exam:'/api/exams/'}[button.dataset.contentDelete];
      try{
        await api(base+button.dataset.id,{method:'DELETE'});
        msg('Record deleted');
        await contentManager();
      }catch(e){msg(e.message)}
    };
  });

  m.querySelectorAll('[data-content-edit]').forEach(button=>{
    button.onclick=async()=>{
      const type=button.dataset.contentEdit,id=button.dataset.id;
      try{
        const urls={event:'/api/events',assignment:'/api/assignments?class_code=',material:'/api/materials?class_code=',exam:'/api/exams?class_code='};
        const rows=await api(urls[type]);
        const record=rows.find(x=>String(x.id)===String(id));
        if(!record)return;

        if(type==='event'){
          const title=prompt('Event title',record.title);
          if(title===null)return;
          const date=prompt('Event date/time (ISO)',record.event_date);
          if(date===null)return;
          await api('/api/events/'+id,{method:'PUT',body:JSON.stringify({...record,title,event_date:date})});
        }else if(type==='assignment'){
          const title=prompt('Assignment title',record.title);
          if(title===null)return;
          const due=prompt('Due date/time (ISO)',record.due_at);
          if(due===null)return;
          await api('/api/assignments/'+id,{method:'PUT',body:JSON.stringify({...record,title,due_at:due})});
        }else if(type==='material'){
          const title=prompt('Material title',record.title);
          if(title===null)return;
          await api('/api/materials/'+id,{method:'PUT',body:JSON.stringify({...record,title})});
        }else{
          const subject=prompt('Exam subject',record.subject);
          if(subject===null)return;
          const date=prompt('Exam date/time',record.exam_date);
          if(date===null)return;
          await api('/api/exams/'+id,{method:'PUT',body:JSON.stringify({...record,subject,exam_date:date})});
        }
        msg('Record updated');
        await contentManager();
        events();assignments();materials();exams();
      }catch(e){msg(e.message)}
    };
  });
}
async function loadAdminTools(){if(me?.role!=='ADMIN')return;try{const [u,c]=await Promise.all([api('/api/users'),api('/api/classes')]);$('userAdminList').innerHTML=u.map(x=>'<div class="flex items-center justify-between gap-2 p-2 rounded bg-slate-50 dark:bg-slate-800 text-sm"><span><b>'+E(x.name)+'</b><small class="block text-slate-500">'+E(x.role)+' • '+E(x.email)+'</small></span><div class="flex gap-2"><button class="text-xs text-blue-600" data-edit-user="'+x.id+'">Edit</button><button class="text-xs '+(x.active?'text-red-600':'text-emerald-600')+'" data-toggle-user="'+x.id+'" data-active="'+x.active+'">'+(x.active?'Deactivate':'Activate')+'</button></div></div>').join('')||'<p class="text-sm text-slate-500">No users.</p>';document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=async()=>{try{await api('/api/users/'+b.dataset.toggleUser,{method:'PUT',body:JSON.stringify({active:b.dataset.active!=='1'})});msg('User status updated');loadAdminTools()}catch(e){msg(e.message)}});document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=async()=>{try{const users=await api('/api/users');const u=users.find(x=>String(x.id)===String(b.dataset.editUser));if(!u)return;const name=prompt('Name',u.name);if(name===null)return;const role=prompt('Role (ADMIN/FACULTY/STUDENT)',u.role);if(role===null)return;const classCode=prompt('Class code',u.class_code||'');if(classCode===null)return;const roll=prompt('Roll number',u.roll_no||'');if(roll===null)return;await api('/api/users/'+u.id,{method:'PUT',body:JSON.stringify({name,role:role.toUpperCase(),class_code:classCode,roll_no:roll})});msg('User updated');loadAdminTools()}catch(e){msg(e.message)}});$('classAdminList').innerHTML=c.map(x=>'<div class="flex justify-between p-2 rounded bg-slate-50 dark:bg-slate-800 text-sm"><span><b>'+E(x.code)+'</b> '+E(x.name)+'</span><button class="text-xs text-red-600" data-delete-class="'+x.id+'">Delete</button></div>').join('');document.querySelectorAll('[data-delete-class]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete class?'))return;try{await api('/api/classes/'+b.dataset.deleteClass,{method:'DELETE'});msg('Class deleted');loadAdminTools()}catch(e){msg(e.message)}})}catch(e){msg(e.message)}}
async function loadWorkspaceNotices(){const d=await api('/api/notices?limit=100&includeScheduled=1');$('wmng').innerHTML=d.items.map(x=>'<div class="border dark:border-slate-700 rounded-xl p-3 flex justify-between"><span><b>'+E(x.title)+'</b><small class="block text-slate-500">'+E(x.category)+' • '+E(x.class_code||'All')+'</small></span><span class="flex gap-2"><button class="text-blue-600 text-xs" data-edit-notice="'+E(x.id)+'">Edit</button>'+(me.role==='ADMIN'?'<button class="text-red-600 text-xs" data-delete-notice="'+E(x.id)+'">Delete</button>':'')+'</span></div>').join('')||'<p class="text-sm text-slate-500">No notices.</p>';document.querySelectorAll('[data-edit-notice]').forEach(b=>b.onclick=()=>editN(b.dataset.editNotice));document.querySelectorAll('[data-delete-notice]').forEach(b=>b.onclick=()=>delN(b.dataset.deleteNotice))}

async function editN(id){const x=(await api('/api/notices?limit=100&includeScheduled=1')).items.find(n=>n.id===id);if(!x)return;const title=prompt('Title',x.title),content=title===null?null:prompt('Content',x.content);if(content===null)return;try{await api('/api/notices/'+id,{method:'PUT',body:JSON.stringify({...x,title,content})});msg('Notice updated');loadWorkspaceNotices();notices()}catch(e){msg(e.message)}}
async function delN(id){if(!confirm('Delete notice?'))return;try{await api('/api/notices/'+id,{method:'DELETE'});msg('Notice deleted');loadWorkspaceNotices();notices()}catch(e){msg(e.message)}}
async function refresh(){shell();authUI();if(me?.class_code&&$('class'))$('class').value=me.class_code;await Promise.all([notices(),timetable(),faculty(),events(),assignments(),materials(),exams()]);if(me?.role==='STUDENT')academic();if(me)refreshNoticeBadge();}
if($('form'))$('form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('pass').value})});token=d.token;me=d.user;localStorage.setItem('vsb_token',token);localStorage.setItem('vsb_user',JSON.stringify(me));$('login').classList.add('hidden');authUI();msg('Signed in');await refresh();if(me.role==='ADMIN'||me.role==='FACULTY')workspace()}catch(e){$('err').textContent=e.message}};
$('class').onchange=refresh;$('cat').onchange=notices;$('search').oninput=()=>{clearTimeout(window.st);window.st=setTimeout(notices,250)};$('globalSearch')?.addEventListener('input',e=>{const v=e.target.value.trim();$('search').value=v;tab('notices');notices()});$('noticeTop')?.addEventListener('click',async()=>{if(!me){login();return}const n=await api('/api/notifications');showNotifications(n)});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>tab(b.dataset.tab));refresh().catch(e=>msg(e.message));
